#### File: `lambda_function_payload.zip`

Create a ZIP file containing your Lambda function code. For example, you can use Node.js to write a simple Lambda function that replicates S3 data to your DR account.

```javascript
// index.js
exports.handler = async (event) => {
  const AWS = require('aws-sdk');
  const s3 = new AWS.S3({ region: 'us-west-2' }); // Replace with your region

  try {
    // Get the S3 bucket and object key from the event
    const bucket = event.Records[0].s3.bucket.name;
    const key = event.Records[0].s3.object.key;

    // Get the object from the source S3 bucket
    const data = await s3.getObject({ Bucket: bucket, Key: key }).promise();

    // Put the object in the DR S3 bucket
    await s3.putObject({ Bucket: 'dr-bucket', Key: key, Body: data.Body }).promise();

    console.log(`Replicated ${key} to DR bucket`);
  } catch (err) {
    console.error(err);
  }
};
```

