### `vars/versionBump.groovy`
```groovy
// vars/versionBump.groovy

def call() {
    def commitMessage = sh(returnStdout: true, script: 'git log -1 --format=%s')
    def bumpType = getBumpType(commitMessage)

    if (bumpType) {
        def version = readMavenPom().getVersion()
        def newVersion = bumpVersion(version, bumpType)
        sh "mvn versions:set -DnewVersion=${newVersion}"
        sh 'git config --global user.email "jenkins@example.com"'
        sh 'git config --global user.name "Jenkins"'
        sh "git commit -am 'Bumped version to ${newVersion}'"
    }
}

def getBumpType(String commitMessage) {
    if (commitMessage =~ /^(fix|feat|BREAKING CHANGE)/) {
        if (commitMessage =~ /^BREAKING CHANGE/) {
            return 'major'
        } else if (commitMessage =~ /^feat/) {
            return 'minor'
        } else {
            return 'patch'
        }
    }
    return null
}

def bumpVersion(String version, String bumpType) {
    def parts = version.split('\\.')
    def major = parts[0].toInteger()
    def minor = parts[1].toInteger()
    def patch = parts[2].toInteger()

    switch (bumpType) {
        case 'major':
            major++
            minor = 0
            patch = 0
            break
        case 'minor':
            minor++
            patch = 0
            break
        case 'patch':
            patch++
            break
    }

    return "${major}.${minor}.${patch}"
}
```

