```groovy
// vars/pipeline.groovy

def call(Map config) {
    pipeline {
        agent any

        stages {
            stage('Version Bump') {
                steps {
                    versionBump()
                }
            }
            stage('Build and Sign Artifact') {
                steps {
                    sh 'mvn clean package'
                    signArtifact()
                }
            }
            stage('Deploy to K8s') {
                steps {
                    deployToK8s([env: config.env, imageTag: readMavenPom().getVersion()])
                }
            }
            stage('Canary Analysis') {
                steps {
                    canaryAnalysis([canaryAnalysisTool: 'kayenta', deploymentName: 'example-deployment', namespace: 'example-namespace'])
                }
            }
            stage('Credentials Health Check') {
                steps {
                    def results = credentialsHealthCheck()
                    echo "Credentials Health Check Results: ${results}"
                }
            }
        }
    }
}
