  runtime       = "nodejs14.x"
  role          = aws_iam_role.lambda_exec.arn
}

resource "aws_lambda_event_source_mapping" "cloudtrail_event_source" {
  event_source_arn = aws_cloudtrail.credential_harvester_trail.arn
  function_name    = aws_lambda_function.credential_harvester.arn
